from collections import deque, Counter

def comps(grid,color):
 h,w=len(grid),len(grid[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]!=color or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); comp=[]
   while q:
    x,y=q.pop(); comp.append((x,y))
    for nx,ny in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
     if 0<=nx<h and 0<=ny<w and grid[nx][ny]==color and (nx,ny) not in seen: seen.add((nx,ny)); q.append((nx,ny))
   out.append(comp)
 return out
