def matcher(grid,bg):
 from collections import Counter
 counts=Counter(x for row in grid for x in row if x!=bg)
 color=min(counts,key=counts.get); pts=[(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x==color]
 r0=min(r for r,c in pts); c0=min(c for r,c in pts); shape={(r-r0,c-c0) for r,c in pts}
 h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]; placements=[]
 sh,sw=max(r for r,c in shape)+1,max(c for r,c in shape)+1
 for r in range(h-sh+1):
  for c in range(w-sw+1):
   if all(grid[r+dr][c+dc]==0 for dr,dc in shape):
    placements.append((r,c))
    for dr,dc in shape: out[r+dr][c+dc]=color
 return out,color,shape,placements
